"""Public officials, honor and immaterial property: scoped special procedures."""
import json,sys
from pathlib import Path
CPP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm'
S330='https://scon.stj.jus.br/SCON/pesquisar.jsp?b=SUMU&livre=%40NUM%3D%27330%27'
PER='https://scon.stj.jus.br/SCON/GetInteiroTeorDoAcordao?dt_publicacao=18%2F06%2F2015&num_registro=201500795635'
TIME='https://www.stj.jus.br/sites/portalp/Paginas/Comunicacao/Noticias/12052021-Homologacao-de-pericia-reduz-para-30-dias-prazo-decadencial-em-crime-contra-propriedade-imaterial.aspx'
rows={}
def add(n,s,p,a,c,v,q,t,d,links=()):
 rows['art-'+str(n)]=dict(simples=s,pontos=p,atencao=[a],exemplo=c+' Variação: '+v,prova=q,termos=[dict(termo=t,significado=d)],remissoes=[CPP,*links])
add(513,'Acusação no rito de crimes funcionais precisa suporte documental/justificação ou declaração fundamentada de impossibilidade.', ['Identificar crime funcional e competência aplicável.', 'Não confundir com impeachment político.', 'A impossibilidade precisa ser motivada.'], 'Não aplicar rito a todo crime só porque autor é servidor, nem transformar declaração vazia em justa causa.', 'Acusação de delito funcional vem com suporte pertinente.', 'Crime particular sem vínculo funcional não entra automaticamente no rito pela profissão do acusado.', ['Ser servidor basta para qualquer crime entrar neste rito? Não.', 'Impossibilidade de prova deve ser fundamentada? Sim.'], 'Rito funcional','Procedimento próprio da hipótese legal.')
add(514,'Texto prevê resposta preliminar em quinze dias nos crimes afiançáveis do rito funcional; integrar Súmula330/STJ.', ['Notificação antes do recebimento, distinta de resposta do art. 396-A.', 'STJ dispensa esta resposta preliminar se ação instruída por inquérito.', 'Nomear defensor se residência desconhecida ou acusado fora da jurisdição na hipótese do parágrafo.'], 'Não ensinar dispensa de toda defesa técnica nem usar prazo de quinze para resposta comum de dez; identificar fonte jurisprudencial e caso.', 'Rito funcional sem a situação da súmula exige examinar notificação prévia.', 'Ação precedida de inquérito demanda aplicar leitura STJ, mantendo defesa posterior regular.', ['Súmula330 elimina defesa técnica posterior? Não.', 'Prazo textual preliminar é quinze dias? Sim.'], 'Resposta preliminar funcional','Manifestação anterior ao recebimento, com ressalva jurisprudencial.',[S330])
add(515,'Durante prazo preliminar, acusado ou defensor pode examinar autos e apresentar documentos e justificações.', ['Acesso real é necessário para resposta.', 'Integrar consulta eletrônica quando aplicável.'], 'Não conceder prazo com autos inacessíveis nem interpretar cartório como proibição de acesso eletrônico válido.', 'Defensor consulta suporte da acusação e junta documento explicativo.', 'Arquivo sigiloso deve ser tratado conforme garantias pertinentes, não negar toda ciência defensiva.', ['Resposta pode ter documentos? Sim.', 'Prazo sem acesso efetivo assegura defesa? Não.'], 'Acesso para resposta','Conhecimento do material que permite manifestação técnica.')
add(516,'Juiz rejeita fundamentadamente acusação se resposta o convence da inexistência do crime ou improcedência da ação.', ['Decisão anterior ao recebimento na hipótese do rito.', 'Não rejeitar ou receber sem analisar questão relevante.'], 'Rejeição preliminar não é condenação nem simples concordância obrigatória com toda defesa.', 'Documento defensivo demonstra fundamento para rejeição e juiz explica decisão.', 'Alegação controvertida sem suporte exige análise, não rejeição automática.', ['Decisão exige fundamentação? Sim.', 'Toda alegação defensiva impõe rejeição? Não.'], 'Controle prévio funcional','Exame de admissibilidade após manifestação pertinente.')
add(517,'Recebida acusação, acusado é citado conforme regime do capítulo de citações.', ['Distinguir notificação preliminar e citação processual.', 'Resposta prévia não dispensa atos defensivos posteriores.'], 'Não pular citação apenas porque houve resposta do art. 514.', 'Depois do recebimento, juízo promove citação regular.', 'Ciência de peça anterior não substitui automaticamente chamamento exigido.', ['Notificação anterior dispensa sempre citação? Não.', 'Recebimento precede citação deste dispositivo? Sim.'], 'Citação após recebimento','Chamamento processual distinto da defesa preliminar.')
add(518,'Instrução e demais atos integram procedimento comum atual nas remissões, respeitadas especificidades funcionais.', ['Não restaurar artigos revogados nas antigas remissões.', 'Garantias e ordem probatória atuais permanecem.'], 'Remissão histórica não permite usar rito ordinário anterior à reforma de 2008.', 'Processo segue instrução compatível com disciplina comum atual.', 'Interrogatório e defesa não são suprimidos por aplicar rito funcional.', ['Remissão restaura artigo revogado? Não.', 'Especificidade dispensa defesa? Não.'], 'Integração do rito','Aplicação compatível das normas processuais atuais.')
add(519,'Calúnia ou injúria seguem rito indicado com modificações especiais, salvo outra forma estabelecida por lei especial.', ['Verificar ação penal e competência.', 'JECRIM e lei especial podem ter disciplina própria.', 'Não estender automaticamente a todos os crimes contra honra sem análise.'], 'Não aplicar uma sequência única a qualquer crime de honra sem verificar regime pertinente.', 'Queixa por calúnia é examinada conforme competência e regras especiais aplicáveis.', 'Infração de menor potencial exige verificar rito do Juizado antes de copiar procedimento.', ['Outra lei especial pode estabelecer forma diversa? Sim.', 'Nome genérico crimes de honra resolve sozinho rito? Não.'], 'Rito de honra','Modificações para as hipóteses definidas no artigo.')
add(520,'Antes de receber queixa na hipótese deste rito, juiz oferece oportunidade de reconciliação com oitiva separada das partes.', ['Texto descreve comparecimento separado, sem advogados na tentativa específica e sem termo desse diálogo.', 'Distinguir da formalização de desistência do art. 522.', 'Não suprimir assistência técnica de todo processo.'], 'Tentativa de acordo não pode forçar desistência; regra específica não exclui defensor dos demais atos.', 'Juiz ouve cada parte para avaliar possibilidade de reconciliação.', 'Sem acordo, não inventa desistência nem converte conversa em confissão obrigatória.', ['Tentativa obriga desistência? Não.', 'É anterior ao recebimento da queixa nesta hipótese? Sim.'], 'Reconciliação preliminar','Oportunidade de composição sem imposição de acordo.')
add(521,'Se considerar provável reconciliação após ouvir partes, juiz promove entendimento na sua presença.', ['Avaliar disposição real de composição.', 'Não impor resultado.' ], 'Probabilidade de acordo não equivale a acordo consumado.', 'Partes demonstram interesse e juiz promove diálogo de composição.', 'Persistindo oposição, não declarar reconciliação fictícia.', ['Probabilidade é acordo já concluído? Não.', 'Entendimento ocorre na presença do juiz? Sim.'], 'Entendimento entre partes','Etapa de tentativa de reconciliação.')
add(522,'Reconciliação leva ao arquivamento após termo de desistência assinado pelo querelante.', ['Formalização da vontade relevante.', 'Distinguir diálogo sem termo e ato conclusivo documentado.'], 'Não arquivar só porque juiz achou acordo possível, sem condição prevista.', 'Querelante assina desistência após reconciliação e queixa é arquivada.', 'Promessa informal sem formalização pertinente não é termo assinado.', ['Querelante assina termo? Sim.', 'Possibilidade de acordo basta ao arquivamento? Não.'], 'Desistência formal','Documentação do resultado reconciliatório.')
add(523,'Exceção da verdade/notoriedade permite contestação pelo querelante em dois dias e prova testemunhal nos limites.', ['Pode utilizar testemunhas já arroladas.', 'Substituição/complementação respeita máximo legal.', 'Cabimento da exceção depende da lei penal aplicável.'], 'Não presumir exceção da verdade cabível em todo crime de honra.', 'Oferecida exceção cabível, querelante contesta e indica prova pertinente.', 'Injúria não ganha automaticamente defesa de verdade só por este rito.', ['Prazo de contestação é dois dias? Sim.', 'Rito torna exceção cabível em qualquer crime? Não.'], 'Contestação da exceção','Resposta ao incidente com prova legalmente admitida.')
add(524,'Propriedade imaterial segue procedimento comum com as modificações próprias deste capítulo.', ['Identificar crime e modalidade de ação.', 'Art. 530-A separa queixa; 530-I distingue ações públicas.', 'Não confundir direito civil autoral e imputação penal.'], 'Nem toda controvérsia de titularidade configura crime ou o mesmo rito.', 'Suspeita de violação autoral exige identificar tipo e iniciativa da ação.', 'Debate contratual sem elementos penais não vira ação criminal automaticamente.', ['Modalidade de ação importa? Sim.', 'Conflito civil sempre é crime? Não.'], 'Propriedade imaterial','Bem protegido cuja infração penal tem requisitos próprios.')
add(525,'Se infração deixa vestígio na hipótese do rito, acusação deve vir com exame pericial dos objetos que formam corpo de delito.', ['Integrar art. 530-A e ação específica.', 'Distinguir constatação técnica de confissão.', 'Não admitir falsificação de laudo para preencher requisito.'], 'Confissão não substitui automaticamente perícia exigida de vestígios.', 'Objetos são periciados para instruir queixa pertinente.', 'Foto genérica não é laudo completo por mera denominação.', ['Vestígio exige cuidado pericial? Sim.', 'Confissão sempre elimina exame? Não.'], 'Corpo de delito imaterial','Vestígios examinados para comprovar infração.')
add(526,'Prova do direito à ação é necessária para receber queixa e ordenar diligência preliminar requerida pelo ofendido.', ['Identificar legitimidade e titularidade pertinente.', 'Não antecipar conclusão de culpa.'], 'Dizer fui prejudicado não prova sozinho direito de agir em qualquer situação.', 'Titular apresenta suporte de legitimidade para medida preliminar.', 'Terceiro sem direito demonstrado não obtém automaticamente busca penal privada.', ['Legitimidade precisa ser demonstrada? Sim.', 'Isso já prova culpa do acusado? Não.'], 'Direito à ação','Condição para iniciativa privada e diligência requerida.')
add(527,'Busca/apreensão preparatória na ação privada segue dois peritos nomeados e laudo em três dias após diligência.', ['Distinção confirmada pelo STJ entre iniciativa privada e pública.', 'Requerente pode impugnar laudo contrário; juiz decide fundamento.', 'Não transpor indiscriminadamente regra geral de um perito oficial.'], 'Distinguir perícia de apreensão na ação privada do regime dos arts. 530-B seguintes.', 'Dois peritos verificam fundamento na diligência preparatória privada.', 'Ação pública tem disciplina própria e não recebe automaticamente mesmo procedimento.', ['Laudo tem prazo de três dias após diligência? Sim.', 'Rito privado e público são sempre iguais? Não.'], 'Perícia preparatória privada','Controle técnico específico antes da queixa.',[PER])
add(528,'Encerradas diligências, autos vão ao juiz para homologar laudo.', ['Homologação é ato judicial.', 'Marco pode repercutir no prazo do art. 529.'], 'Data do exame e data de homologação não são necessariamente iguais.', 'Juiz recebe diligências concluídas e examina homologação.', 'Não contar prazo da homologação apenas da assinatura do perito.', ['Homologação é ato do juiz? Sim.', 'É sempre a mesma data do laudo? Não.'], 'Homologação do laudo','Ato judicial de exame da diligência realizada.')
add(529,'Queixa fundada em apreensão/perícia tem prazo de trinta dias após homologação, harmonizado com decadência geral.', ['STJ: ciência de autoria inicia seis meses; homologação no intervalo reduz a trinta dias.', 'Não usar homologação para reviver direito já decaído.', 'Parágrafo: vista ao MP na situação de ação pública descrita.'], 'Não ensinar trinta dias como substituto isolado universal dos seis meses em toda propriedade imaterial.', 'Homologação durante prazo geral exige observar também prazo específico.', 'Se direito já decaiu, laudo posterior não o ressuscita.', ['Homologação revive direito decaído? Não.', 'Trinta dias exige integração com prazo geral? Sim.'], 'Prazo especial da queixa','Marco pericial integrado à decadência penal.',[TIME])
add(530,'Flagrante sem libertação reduz a oito dias o prazo referido no art. 529 na hipótese especial.', ['Condições cumulativas: flagrante e não posto em liberdade.', 'Marco deve ser lido com artigo anterior.', 'Não é prazo geral de resposta ou de toda queixa.'], 'Não aplicar oito dias a qualquer infração só porque houve prisão alguma vez.', 'Flagrante e permanência preso exigem verificar prazo especial do capítulo.', 'Liberado não preenche condição apenas por ter sido autuado antes.', ['Libertação altera condição da hipótese? Sim.', 'É prazo universal da resposta à acusação? Não.'], 'Prazo especial reduzido','Regra da hipótese de flagrante sem libertação.')
add('530-a','Arts. 524–530 aplicam-se aos crimes processados mediante queixa.', ['Modalidade de ação delimita remissão.', 'Contrastar com art. 530-I nas ações públicas.'], 'Não aplicar o bloco privado a toda violação autoral sem identificar iniciativa.', 'Crime de ação privada segue modificações referidas.', 'Tipo com ação pública exige examinar outro conjunto de regras.', ['Artigo delimita ao procedimento por queixa? Sim.', 'Toda ação autoral é privada? Não.'], 'Delimitação da queixa','Separação entre regimes de iniciativa penal.')
add('530-b','Nos §§1º–3º do art. 184/CP, apreender bens ilícitos e meios destinados principalmente à prática ilícita.', ['Produtos/reproduções em totalidade.', 'Equipamentos, suportes e materiais com destinação precípua.', 'Respeitar legalidade da diligência e documentação.'], 'Não confiscar qualquer bem pessoal só por estar no local.', 'Equipamento principalmente utilizado para reprodução ilícita é examinado na apreensão.', 'Computador sem vínculo de destinação precípua não entra automaticamente só por proximidade.', ['Todo bem próximo é apreendido automaticamente? Não.', 'Destinação principal do equipamento importa? Sim.'], 'Destinação precípua','Uso principal voltado à prática ilícita.')
add('530-c','Apreensão gera termo com descrição dos bens e origem, assinado por duas ou mais testemunhas.', ['Integrar inquérito ou processo.', 'Descrição permite controle e rastreabilidade.'], 'Não registrar lote como objetos diversos sem dados suficientes.', 'Termo individualiza material e informações de procedência.', 'Assinatura de uma só testemunha não cumpre número textual exigido.', ['São pelo menos duas testemunhas? Sim.', 'Termo integra investigação/processo? Sim.'], 'Termo de apreensão','Registro dos bens e da diligência.')
add('530-d','Após apreensão, perícia e laudo integram procedimento, por oficial ou, faltando, tecnicamente habilitado.', ['Examinar bens apreendidos e autenticidade pertinente.', 'Integrar jurisprudência sobre amostragem no tipo específico.', 'Não exigir automaticamente identificação de cada titular em hipótese sumulada.'], 'A redação todos os bens não autoriza ignorar perícia nem resolver regras de amostragem sem fonte e hipótese específica.', 'Material apreendido é examinado com técnica documentada e laudo.', 'Declaração policial sem exame técnico não é automaticamente laudo.', ['Laudo deve integrar procedimento? Sim.', 'Ausência de oficial elimina toda possibilidade de exame? Não.'], 'Perícia autoral','Exame técnico das características relevantes do material.')
add('530-e','Titulares autorais/conexos são fiéis depositários dos bens, à disposição do juiz ao ajuizar ação.', ['Depósito não é autorização de venda ou descarte livre.', 'Preservar apresentação judicial.'], 'Ser titular do direito não transforma apreensão em aquisição irrestrita dos objetos.', 'Depositário conserva bens para disponibilizar ao juízo.', 'Destruir sem hipótese e ordem próprias pode prejudicar prova.', ['Depositário pode vender livremente? Não.', 'Bens devem ficar disponíveis ao juiz? Sim.'], 'Fiel depósito','Guarda com dever de preservação e apresentação.')
add('530-f','Juiz pode destruir reprodução ilícita a pedido da vítima nas hipóteses legais, preservando possibilidade de corpo de delito.', ['Sem impugnação da ilicitude ou sem autor identificado para iniciar ação.', 'Decisão judicial e pedido exigidos.', 'Preservação probatória importa.'], 'Não destruir automaticamente tudo na apreensão nem eliminar vestígio necessário.', 'Vítima pede destruição em hipótese legal e juiz assegura preservação pertinente.', 'Havendo controvérsia técnica relevante, não presumir ilicitude incontroversa.', ['Pedido da vítima é previsto? Sim.', 'Destruição dispensa cuidado com prova? Não.'], 'Destruição antecipada autorizada','Destinação judicial sujeita às condições legais.')
add('530-g','Na condenação, juiz pode determinar destruição dos bens ilícitos e perdimento de equipamentos principalmente destinados à reprodução.', ['Perdimento em favor da Fazenda Nacional.', 'Destinação: destruir, doar aos entes/instituições indicados ou incorporar à União por interesse/economia.', 'Não retornar aos canais de comércio.'], 'Não estender perdimento a equipamento sem destinação precípua nem vender de volta ao comércio.', 'Equipamento destinado ao ilícito recebe destinação judicial legal.', 'Bem de uso legítimo sem requisito não é perdido automaticamente por estar apreendido.', ['Pode retornar ao comércio? Não.', 'Uso principal ilícito importa no equipamento? Sim.'], 'Destinação na condenação','Consequências patrimoniais específicas da sentença.')
add('530-h','Associação de titulares pode atuar em próprio nome como assistente se crime do art.184 lesar associado.', ['Identificar direito e associado atingido.', 'Não confundir assistente com substituição ilimitada do MP.'], 'Vínculo associativo e hipótese penal são condições, não ingresso automático de qualquer entidade.', 'Associação demonstra lesão a membro e pede assistência.', 'Entidade sem relação com titular lesado não recebe legitimidade só por interesse genérico.', ['Atuação pode ser em próprio nome? Sim.', 'Qualquer entidade tem acesso automático? Não.'], 'Assistência associativa','Atuação prevista de associação de titulares lesados.')
add('530-i','Nas ações públicas condicionadas ou incondicionadas, aplicam-se arts. 530-B–H.', ['Identificar condição de procedibilidade quando exigida.', 'Não confundir ação condicionada com queixa privada.'], 'Referência a ação pública não elimina representação quando legalmente necessária.', 'Tipo de ação pública utiliza apreensão, perícia e demais regras pertinentes.', 'Se condicionada, verificar manifestação exigida antes de presumir ação livre de condição.', ['Abrange pública condicionada? Sim.', 'Condicionada equivale a queixa privada? Não.'], 'Regime da ação pública','Disciplina especial para iniciativa acusatória pública.')
rows['art-530-d']['pontos'].append('Súmula574/STJ: materialidade da violação autoral pode ser demonstrada por amostragem dos aspectos externos; dispensa identificar titulares na hipótese sumulada.')
rows['art-530-d']['remissoes'].append('https://processo.stj.jus.br/jurisprudencia/externo/informativo/?acao=pesquisarumaedicao&livre=%40cod%3D%270585%27')
rows['art-530-d']['exemplo']='Lote de mídias no art.184, §2º: laudo por amostragem dos aspectos externos pode demonstrar materialidade conforme Súmula574. Variação: amostragem não equivale a dispensar laudo nem demonstra por si todos os outros elementos do crime.'
rows['art-530-d']['prova']=['Precisa sempre periciar individualmente cada mídia para materialidade nessa hipótese? Não, amostragem é admitida.', 'Amostragem dispensa laudo? Não.']
assert len(rows)==27
Path(sys.argv[1]).write_text(json.dumps({'course_slug':'codigo-processo-penal','units':rows},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(len(rows),'special procedure units reviewed')
